import{_ as s,a0 as a,w as p,s as i,ao as l,I as r,x as n,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Turn Off Shutdown ／ Restart Confirmation In Ubuntu","title":"每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Turn Off Shutdown ／ Restart Confirmation In Ubuntu.md","filePath":"[post].md"}'),d={name:"201402/Daily Ubuntu Tips – Turn Off Shutdown ／ Restart Confirmation In Ubuntu.md"};function b(f,t,m,T,g,w){const u=a("Link");return p(),i("div",null,[t[11]||(t[11]=l(`<h1 id="每日-ubuntu-小技巧——關閉-ubuntu-中的關機-重啓確認" tabindex="-1">每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認 <a class="header-anchor" href="#每日-ubuntu-小技巧——關閉-ubuntu-中的關機-重啓確認" aria-label="Permalink to “每日 Ubuntu 小技巧——關閉 Ubuntu 中的關機/重啓確認”">​</a></h1><p>對於 Ubuntu 新手來説，有很多新東西要學，但是網上很多教程不是針對新手的。</p><p>在這裏，我們不走尋常路。不能説全部的教程都是為初學者準備，但至少大部分是。</p><p>這篇文章也是一篇新手教程，並且展示如何在每次執行關機、重啓、註銷時禁用確定框。</p><p>Ubuntu 總是配置好了一個對話框，每當你要關機、重啓或者註銷時提示你。</p><p>這是一個保護措施，防止你本不打算這樣做卻錯誤關機或重啓。</p><p>不是所有人都想每次關機的時候被詢問。忙碌的小夥伴們可能就讓自己的電腦那麼醒着，因為他執行了關閉命令，卻忘了確認那個該死的對話框。</p><p>這個教程將會指導你每一次關機的時候如何避免那個對話框。</p><p>當這個特性被激活，你將會收到下面的提示。</p><blockquote><p>Are you sure you want to close all programs and shutdown your computer?</p></blockquote><p>運行下面命令關掉它。</p><p>按下鍵盤上的 <strong>Ctrl – Alt – T</strong> 打開終端。然後敲擊下面的命令</p><pre><code>gsettings set com.canonical.indicator.session suppress-logout-restart-shutdown true
</code></pre><p>就這麼簡單，你再也不會被該死的確認對話框騷擾了。</p><p>如果想恢復這個對話框，敲下面的命令就可以了</p><pre><code>gsettings set com.canonical.indicator.session suppress-logout-restart-shutdown false
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/shutdownubuntuconfirm.png" alt=""></p><p>乾巴爹！</p><hr>`,19)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-turn-off-shutdown-restart-confirmation-in-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-turn-off-shutdown-restart-confirmation-in-ubuntu/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=n("譯者：",-1)),e(u,{href:"https://github.com/ggaaooppeenngg"},{default:o(()=>[...t[2]||(t[2]=[n("ggaaooppeenngg",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),e(u,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),e(u,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const h=s(d,[["render",b]]);export{_ as __pageData,h as default};
